eval("const {\n  getCurrentDateTime\n} = __webpack_require__(/*! ../utilities/dateTime.js */ \"./utilities/dateTime.js\");\nconst getCaseById = (caseId, userId) => {\n  const url = 'https://portal.medscred.com/';\n  const getCaseByIdQuery = `SELECT \n        a.first_name AS hospital_name,\n        p.id, \n        p.id AS patient_id, \n        p.first_name, \n        p.middle_name, \n        p.last_name, \n        p.email, \n        p.phone_number, \n        pci.id AS case_id, \n        lt.type AS loan_type, \n        pci.treatment_name, \n        pci.treatment_type, \n        pci.cash_type, \n        pci.estimated_amount, \n        pci.estimated_stay, \n        pci.patient_admitted, \n        pci.expected_doa, \n        CASE \n            WHEN pkd.doctor_prescription LIKE 'upload%' THEN CONCAT('${url}', pkd.doctor_prescription)\n            ELSE pkd.doctor_prescription\n        END AS doctor_prescription, \n        CASE\n            WHEN pkd.reports LIKE 'upload%' THEN CONCAT('${url}', pkd.reports)\n            ELSE pkd.reports\n        END AS reports,\n        CASE\n            WHEN pkd.past_treatment_record LIKE 'upload%' THEN CONCAT('${url}', pkd.past_treatment_record)\n            ELSE pkd.past_treatment_record\n        END AS past_treatment_record,\n        CASE\n            WHEN pkd.patient_passport_photo LIKE 'upload%' THEN CONCAT('${url}', pkd.patient_passport_photo)\n            ELSE pkd.patient_passport_photo\n        END AS patient_passport_photo,\n        CASE\n            WHEN pkd.patient_adhaar_card LIKE 'upload%' THEN CONCAT('${url}', pkd.patient_adhaar_card)\n            ELSE pkd.patient_adhaar_card\n        END AS patient_aadhar_card,\n        CASE\n            WHEN pkd.patient_insurance_card LIKE 'upload%' THEN CONCAT('${url}', pkd.patient_insurance_card)\n            ELSE pkd.patient_insurance_card\n        END AS patient_insurance_card,\n        CASE\n            WHEN pkd.primary_insured_adhaar LIKE 'upload%' THEN CONCAT('${url}', pkd.primary_insured_adhaar)\n            ELSE pkd.primary_insured_adhaar\n        END AS primary_insured_aadhar,\n        CASE\n            WHEN pkd.primary_insured_insurance LIKE 'upload%' THEN CONCAT('${url}', pkd.primary_insured_insurance)\n            ELSE pkd.primary_insured_insurance\n        END AS primary_insured_insurance,\n        CASE\n            WHEN pkd.primary_insured_pan LIKE 'upload%' THEN CONCAT('${url}', pkd.primary_insured_pan)\n            ELSE pkd.primary_insured_pan\n        END AS primary_insured_pan,\n        pci.created_at, \n        s.status_name \n        FROM \n            patients p \n        LEFT JOIN \n            patient_cases_info pci ON p.id = pci.patient_id \n        LEFT JOIN \n            status_logs ss ON pci.id = ss.case_id \n        LEFT JOIN \n            loan_type lt ON pci.loan_type = lt.id \n        LEFT JOIN \n            patient_kyc_details pkd ON pci.id = pkd.case_id \n        LEFT JOIN \n            status s ON ss.status = s.id \n        LEFT JOIN\n            hospital_patient_case_access hpca ON pci.id = hpca.case_id\n        LEFT JOIN\n            admin a ON hpca.hospital_id = a.id\n        LEFT JOIN\n            patient_payment_details ppd ON pci.id = ppd.case_id\n        WHERE \n        p.is_active = '1' \n        AND ss.is_active = '1' \n        AND pci.id = ${caseId} AND ppd.nbfc = ${userId}`;\n  return getCaseByIdQuery;\n};\nconst preLoanDetails = (caseId, cibil_score, fileUrl, userremark) => {\n  const updateCaseIdQuery = `UPDATE patient_loan_details SET cibil_score='${cibil_score}',cibil_approval_doc='${fileUrl}',userremark='${userremark}',updated_at='${getCurrentDateTime()}' WHERE case_id = '${caseId}'`;\n  return updateCaseIdQuery;\n};\nmodule.exports = {\n  getCaseById,\n  preLoanDetails\n};\n\n//# sourceURL=webpack://server/./services/patient.query.service.js?");

